INSERT INTO `ann_announcement` (`id`, `title`, `subtitle`, `summary`, `content`, `cover_image`, `category_id`, `author_id`, `dept_id`, `campus`, `status`, `visibility`, `priority`, `is_top`, `is_banner`, `is_red_head`, `allow_comment`, `need_receipt`, `publish_time`, `expire_time`, `audit_user_id`, `audit_time`, `audit_remark`, `view_count`, `receipt_count`, `target_count`, `version`, `keywords`, `create_by`, `create_time`, `update_time`, `deleted`)
VALUES (301, '关于开展2024年春季学期期中教学检查的通知', '教务处统一部署', '学校将于第9至第10教学周开展期中教学检查，请各学院按时提交自查报告。', '<p>各学院、各教学单位：</p><p>为全面掌握本学期教学运行情况，学校决定于第9至第10教学周开展期中教学检查。检查内容包括课堂教学秩序、实验实践环节、教学资料归档等。</p><p>请各学院于第10教学周周五17:00前提交《期中教学检查自查报告》。</p><p>教务处</p>', '/upload/cover/teach-check.png', 202, 102, 1, '加利顿主校区', 'PUBLISHED', 'ALL', 'IMPORTANT', 1, 1, 0, 1, 1, '2024-04-08 09:00:00', '2024-06-30 23:59:59', 102, '2024-04-07 16:20:00', '内容合规，同意发布', 1860, 5, 120, 1, '教学检查,期中,自查报告', '101', '2024-04-06 10:12:00', '2024-04-08 09:00:00', 0),
       (302, '加利顿大学第十六届校园科技文化节活动预告', '科技点亮青春', '第十六届校园科技文化节将于5月10日开幕，包含创新作品展、编程马拉松与人工智能论坛。', '<p>全体师生：</p><p>第十六届校园科技文化节定于5月10日至5月18日举行，主会场设在大学生活动中心。</p><ul><li>创新作品展：5月10日-12日</li><li>编程马拉松：5月13日-14日</li><li>人工智能前沿论坛：5月16日</li></ul><p>欢迎全校师生踊跃参与。</p>', '/upload/cover/tech-festival.png', 204, 103, 5, '加利顿主校区', 'PUBLISHED', 'ALL', 'NORMAL', 0, 1, 0, 1, 0, '2024-05-01 08:30:00', '2024-05-18 23:59:59', 102, '2024-04-28 10:00:00', '同意发布，注意现场安全预案', 2435, 4, 120, 1, '科技文化节,编程马拉松,论坛', '101', '2024-04-26 14:20:00', '2024-05-01 08:30:00', 0),
       (303, '关于加强校园网络与个人信息安全的提醒', '信息安全月专项', '近期出现仿冒校园门户的钓鱼邮件，请师生勿点击陌生链接并及时修改弱口令。', '<p>全体师生：</p><p>近期监测到仿冒学校门户的钓鱼邮件，发件人地址存在拼写差异，请勿点击邮件中的链接或提交账号密码。</p><p>信息中心提醒：学校不会通过邮件索要密码，请及时修改弱口令并开启二次验证。</p>', '/upload/cover/security-tip.png', 205, 101, 4, '加利顿主校区', 'PUBLISHED', 'ALL', 'URGENT', 1, 0, 1, 0, 1, '2024-05-06 10:00:00', '2024-12-31 23:59:59', 101, '2024-05-06 09:30:00', '紧急公告，直接发布', 3120, 4, 120, 2, '安全提醒,钓鱼邮件,弱口令', '101', '2024-05-06 09:10:00', '2024-05-06 10:00:00', 0),
       (304, '2024年春季校园招聘会参会企业名单公示', '就业服务专区', '68家企业将参加5月25日校园招聘会，名单及展位安排现已公示。', '<p>各位同学：</p><p>2024年春季校园招聘会将于5月25日9:00-16:00在体育馆举行，共68家参会企业，展位安排详见附件。</p><p>请携带简历与学生证入场。</p>', '/upload/cover/job-fair.png', 201, 103, 5, '加利顿主校区', 'SCHEDULED', 'ALL', 'NORMAL', 0, 0, 0, 1, 0, '2024-06-01 09:00:00', '2024-06-30 23:59:59', 102, '2024-05-22 15:40:00', '排期发布，同意', 0, 0, 0, 1, '招聘会,就业,展位', '101', '2024-05-20 11:00:00', '2024-05-22 15:40:00', 0),
       (305, '关于组织申报2024年度校级科研基金项目的通知', '科研处', '校级科研基金项目申报通道已开启，申报截止时间为6月15日。', '<p>各学院、各位教师：</p><p>2024年度校级科研基金项目现开始申报，重点支持人工智能、新能源、生物医药等方向。</p><p>请于6月15日前在科研管理系统提交申报书与预算表。</p>', NULL, 203, 104, 6, '加利顿主校区', 'PENDING', 'ALL', 'IMPORTANT', 0, 0, 0, 1, 0, NULL, '2024-07-31 23:59:59', NULL, NULL, NULL, 0, 0, 0, 1, '科研基金,申报,预算', '104', '2024-05-18 09:20:00', '2024-05-18 09:45:00', 0),
       (306, '关于图书馆暑期开放时间调整的公告', '图书馆办公室', '暑期图书馆开馆时间调整为8:30-17:30，周末闭馆。', '<p>各位读者：</p><p>自7月1日起，图书馆开馆时间调整为每日8:30-17:30，周六周日闭馆，电子资源服务不受影响。</p>', NULL, 202, 103, 1, '加利顿主校区', 'DRAFT', 'ALL', 'NORMAL', 0, 0, 0, 1, 0, NULL, '2024-09-01 23:59:59', NULL, NULL, NULL, 0, 0, 0, 1, '图书馆,暑期,开放时间', '103', '2024-05-21 16:30:00', '2024-05-21 16:30:00', 0),
       (307, '关于调整校车运行线路的通知（草稿待改）', '后勤保障处', '拟调整东校区至主校区班车频次，草稿待完善后重新提交。', '<p>全体师生：</p><p>拟将东校区至主校区班车由每日6班调整为8班，具体时刻表待定。</p>', NULL, 201, 105, 3, '加利顿主校区', 'REJECTED', 'ALL', 'NORMAL', 0, 0, 0, 1, 0, NULL, NULL, 102, '2024-05-15 11:20:00', '班车时刻表缺失，请补充后重新提交', 0, 0, 0, 1, '校车,班车,线路', '105', '2024-05-14 10:40:00', '2024-05-15 11:20:00', 0),
       (308, '加利顿大学2024年实验室设备采购招标公告', '招标编号 JLDUZB-2024-018', '拟采购高性能计算服务器与网络存储设备，投标截止6月20日。', '<p>加利顿大学就高性能计算服务器与网络存储设备进行公开招标，欢迎符合资质的供应商参与。</p><p>投标截止时间：2024年6月20日14:00，开标地点：行政楼302会议室。</p>', '/upload/cover/bidding.png', 206, 102, 6, '加利顿主校区', 'PUBLISHED', 'COLLEGE', 'NORMAL', 0, 0, 1, 0, 0, '2024-05-12 09:00:00', '2024-06-20 14:00:00', 102, '2024-05-12 08:30:00', '招标类公告免审核直接发布', 980, 2, 32, 1, '招标,采购,服务器', '101', '2024-05-11 17:00:00', '2024-05-12 09:00:00', 0),
       (309, '关于临时调整主校区停车区域的紧急通知', '已于5月9日撤回', '因道路施工临时调整停车区域，该通知已随施工结束撤回。', '<p>因主校区东门道路施工，5月7日至5月9日临时调整停车区域。</p>', NULL, 201, 101, 4, '加利顿主校区', 'WITHDRAWN', 'ALL', 'URGENT', 0, 0, 0, 1, 0, '2024-05-07 07:30:00', '2024-05-09 18:00:00', 102, '2024-05-07 07:00:00', '紧急公告，先发布后报备', 640, 0, 0, 1, '停车,施工,紧急', '101', '2024-05-07 06:50:00', '2024-05-09 18:20:00', 0),
       (310, '2023-2024学年第一学期期末考试安排（已归档）', '教务处', '上学期期末考试安排，考试结束后已归档留档。', '<p>2023-2024学年第一学期期末考试于1月8日至1月19日进行，具体安排见附件。</p>', NULL, 202, 102, 1, '加利顿主校区', 'ARCHIVED', 'ALL', 'NORMAL', 0, 0, 0, 1, 1, '2023-12-20 09:00:00', '2024-01-31 23:59:59', 101, '2023-12-19 15:00:00', '同意发布', 4520, 4, 120, 1, '期末考试,归档,考务', '101', '2023-12-18 10:00:00', '2024-02-01 00:10:00', 0),
       (311, '关于举办第十二届青年教师教学基本功比赛的通知', '教师发展中心', '比赛报名截至5月30日，决赛于6月12日举行。', '<p>各学院：</p><p>第十二届青年教师教学基本功比赛分预赛与决赛两个阶段，决赛于6月12日在明德楼报告厅举行。</p>', '/upload/cover/teaching-match.png', 204, 104, 2, '加利顿主校区', 'PUBLISHED', 'COLLEGE', 'NORMAL', 0, 0, 0, 1, 0, '2024-05-15 09:00:00', '2024-06-12 23:59:59', 102, '2024-05-14 16:00:00', '同意发布', 1120, 2, 32, 2, '教学比赛,青年教师,基本功', '101', '2024-05-13 10:30:00', '2024-05-15 09:00:00', 0),
       (312, '关于校园一卡通系统升级停机维护的公告', '信息中心', '一卡通系统将于5月28日凌晨停机维护4小时。', '<p>全体师生：</p><p>信息中心将于5月28日00:00-04:00对一卡通系统进行升级维护，期间无法刷卡消费与充值，请提前安排。</p>', '/upload/cover/card-system.png', 205, 101, 4, '加利顿校区(分校区)', 'PUBLISHED', 'CLASS', 'IMPORTANT', 1, 1, 0, 1, 1, '2024-05-24 09:00:00', '2024-05-28 12:00:00', 101, '2024-05-23 20:00:00', '同意发布', 1520, 4, 46, 1, '一卡通,停机维护,升级', '101', '2024-05-23 17:20:00', '2024-05-24 09:00:00', 0);

