INSERT INTO `ann_version` (`id`, `announcement_id`, `version_no`, `title`, `content`, `editor_id`, `editor_name`, `change_log`, `create_time`)
VALUES (701, 303, 1, '关于加强校园网络安全的提醒', '<p>全体师生：近期请勿点击陌生邮件中的链接。</p>', 101, '超级管理员', '初稿创建', '2024-05-06 09:10:00'),
       (702, 303, 2, '关于加强校园网络与个人信息安全的提醒', '<p>全体师生：</p><p>近期监测到仿冒学校门户的钓鱼邮件，请勿点击邮件中的链接或提交账号密码。</p><p>信息中心提醒：学校不会通过邮件索要密码，请及时修改弱口令并开启二次验证。</p>', 101, '超级管理员', '补充个人信息保护与二次验证说明', '2024-05-06 09:40:00'),
       (703, 311, 1, '关于举办青年教师教学基本功比赛的通知', '<p>各学院：请组织青年教师报名参加教学基本功比赛。</p>', 104, '陈明远', '初稿创建', '2024-05-13 10:30:00'),
       (704, 311, 2, '关于举办第十二届青年教师教学基本功比赛的通知', '<p>各学院：</p><p>第十二届青年教师教学基本功比赛分预赛与决赛两个阶段，决赛于6月12日在明德楼报告厅举行。</p>', 104, '陈明远', '补充届次与决赛时间地点', '2024-05-15 08:40:00');

